package com.nigson.commerce.fulfillment;
import java.util.*;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.security.PrivateWorkload;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** PandaGo no-label acknowledgement, metadata, history and outbox in one local transaction. */
public final class CarrierResultService {
 private record Intent(UUID order,UUID booking,String mode,String snapshotHash){}
 private final JdbcTemplate jdbc;private final JdbcShipmentRepository repository;private final FulfillmentPolicy policy;private final PlatformStore commands;private final AuditWriter audit;private final Clock clock;private final String environment;private final TransactionTemplate read;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public CarrierResultService(JdbcTemplate jdbc,JdbcShipmentRepository repository,FulfillmentPolicy policy,PlatformStore commands,AuditWriter audit,PlatformTransactionManager manager,Clock clock,String environment,io.micrometer.core.instrument.MeterRegistry metrics){if(!Set.of("local","test","dev","qa","stage","prod").contains(environment))throw new IllegalArgumentException("CARRIER_PRIVATE_STORAGE_REQUIRED");this.jdbc=jdbc;this.repository=repository;this.policy=policy;this.commands=commands;this.audit=audit;this.clock=clock;this.environment=environment;this.metrics=metrics;read=new TransactionTemplate(manager);read.setReadOnly(true);read.setTimeout(3);read.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);}
 private String principal(PrivateWorkload.Proof proof){if(proof==null||proof.actor()!=null||!"nigson-integration".equals(proof.client())||proof.subject()==null||!proof.subject().matches("[A-Za-z0-9._:-]{1,100}")||!PrivateWorkload.ROUTES.stream().anyMatch(r->r.api().equals("API-120")&&r.equals(proof.route())))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return proof.client();}
 private Intent intent(UUID id,boolean lock){UUID orderId=repository.orderId(id);var order=repository.order(orderId,lock);var row=jdbc.queryForMap("SELECT provider,booking_request_id,package_snapshot::text FROM commerce.shipment WHERE id=?"+(lock?" FOR UPDATE":""),id);if(!"PANDAGO".equals(row.get("provider"))||row.get("booking_request_id")==null||!"NGN".equals(order.get("currency_code")))throw FulfillmentValues.rule();var snapshot=EventCodec.JSON.readTree(row.get("package_snapshot").toString());String mode=snapshot.path("mode").asString();var frozen=EventCodec.JSON.readTree(order.get("carrier_snapshot").toString());if(!mode.equals(frozen.path("mode").asString())||!snapshot.path("bookingReference").asString().equals(row.get("booking_request_id").toString()))throw FulfillmentValues.rule();policy.require(mode,"PANDAGO");policy.requireAccount(frozen.path("accountHash").asString());return new Intent(orderId,(UUID)row.get("booking_request_id"),mode,EventCodec.hash(snapshot));}
 public FulfillmentValues.Shipment accept(PrivateWorkload.Proof proof,UUID id,CarrierResultValues.Result input,UUID correlation){String subject=principal(proof);ApiValues.uuid(id==null?null:id.toString());ApiValues.uuid(correlation==null?null:correlation.toString());if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("PROVIDER_CALL_INSIDE_TRANSACTION");if(input.occurredAt().isAfter(clock.instant().plusSeconds(5)))throw ApiValues.invalid();policy.require(input.mode(),"PANDAGO");var body=EventCodec.JSON.valueToTree(Map.of("shipment",id,"result",input));String key=input.commandId().toString();
  if(commands.completed(subject,"API-120",key))return decode(commands.executeLocal(subject,"API-120",key,body,db->{throw new IllegalStateException("CARRIER_ACKNOWLEDGEMENT_MISSING");}));
  Intent captured=read.execute(status->intent(id,false));if(!captured.mode().equals(input.mode()))throw new Problem.Failure(ProblemCode.PROVIDER_MODE_MISMATCH);policy.tracking(input.trackingUrl());
  return decode(commands.executeLocal(subject,"API-120",key,body,db->apply(id,input,correlation,captured,subject)));
 }
 private PlatformStore.Response apply(UUID id,CarrierResultValues.Result input,UUID correlation,Intent captured,String subject){
  Intent current=intent(id,true);if(!current.equals(captured))throw FulfillmentValues.rule();var before=repository.find(id,false);if(before.version()==Long.MAX_VALUE)throw FulfillmentValues.rule();String known=jdbc.queryForObject("SELECT provider_reference FROM commerce.shipment WHERE id=?",String.class,id);boolean uncertain=Set.of("UNKNOWN","FAILED").contains(Objects.requireNonNullElse(input.bookingState(),""));if(uncertain){if(!input.reference().equals(current.booking().toString()))throw FulfillmentValues.rule();}else if(known!=null&&!known.equals(input.reference()))throw FulfillmentValues.rule();
  var latest=jdbc.queryForObject("SELECT max(occurred_at) FROM commerce.shipment_event WHERE shipment_id=? AND source='PANDAGO' AND status IN ('BOOKED','SHIPPED','DELIVERED','CANCELLED','EXCEPTION')",java.sql.Timestamp.class,id);boolean older=latest!=null&&input.occurredAt().isBefore(latest.toInstant());boolean booked=known!=null&&Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.shipment_event WHERE shipment_id=? AND source='PANDAGO' AND status='BOOKED')",Boolean.class,id));String next=CarrierResultStates.next(before.status(),input,older,booked);
  if(next.equals("DELIVERED")&&!before.status().equals("DELIVERED"))repository.delivered(id,before.version(),new FulfillmentValues.Delivery(input.occurredAt(),"Verified carrier delivery evidence"),subject);
  else if(!next.equals(before.status())||!older&&input.trackingUrl()!=null&&!Objects.equals(before.trackingUrl(),input.trackingUrl())){jdbc.update("UPDATE commerce.shipment SET status=?,provider_reference=CASE WHEN ? THEN ? ELSE provider_reference END,tracking_url=CASE WHEN ? THEN coalesce(?,tracking_url) ELSE tracking_url END,version=version+1,updated_at=?,updated_by=? WHERE id=?",next,"BOOKED".equals(input.bookingState()),input.reference(),!older,input.trackingUrl(),java.sql.Timestamp.from(clock.instant()),subject,id);}
  String eventStatus=input.bookingState()==null?input.status():input.bookingState();jdbc.update("INSERT INTO commerce.shipment_event(id,created_by,shipment_id,source,event_key,status,occurred_at) VALUES (?,?,?,'PANDAGO',?,?,?)",EventCodec.uuid7(clock.instant()),subject,id,input.commandId().toString(),eventStatus,java.sql.Timestamp.from(input.occurredAt()));repository.progress(current.order(),subject);var after=repository.find(id,false);
  audit.append(subject,AuditValues.ActorKind.SERVICE,AuditValues.Action.SHIPMENT_PROVIDER_RESULT,AuditValues.Resource.SHIPMENT,id,correlation,AuditValues.Reason.VERIFIED_PROVIDER,Map.of("state",before.status(),"version",before.version()),Map.of("state",after.status(),"version",after.version()),null);
  if(after.version()!=before.version()){var event=new LinkedHashMap<String,Object>();event.put("event_id",EventCodec.uuid7(clock.instant()));event.put("event_type","shipment.changed.v1");event.put("schema_version",1);event.put("producer","commerce");event.put("occurred_at",clock.instant());event.put("aggregate_id",id);event.put("aggregate_version",after.version());event.put("organization_id",repository.organization(current.order()));event.put("correlation_id",correlation);event.put("traceparent",null);event.put("payload",Map.of("shipment_id",id,"order_id",current.order(),"status",after.status(),"occurred_at",input.occurredAt()));commands.append(EventCodec.JSON.writeValueAsString(event),subject);}
  TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.fulfillment.provider-results","status",eventStatus).increment();}});return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),id);
 }
 private FulfillmentValues.Shipment decode(PlatformStore.Response response){return EventCodec.JSON.treeToValue(response.body(),FulfillmentValues.Shipment.class);}
}
